WITH flattened_attrs AS (SELECT id, host, level, COALESCE(context['region'], 'none') AS region_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs) SELECT level, CASE WHEN duration_sec >= 3.5 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, COUNT(DISTINCT region_or_default) AS distinct_region_or_defaults, ROUND(AVG(duration_sec), 2) AS avg_duration_sec FROM flattened_attrs GROUP BY level, CASE WHEN duration_sec >= 3.5 THEN 'HIGH' ELSE 'LOW' END ORDER BY distinct_region_or_defaults ASC NULLS FIRST;
